"""Hand-written lexer and recursive-descent parser for minisql.

The only public entry point is :func:`parse`, which turns a ``SELECT``
statement into a :class:`minisql.ast.Query`.  Every lexical or grammatical
problem is reported as :class:`minisql.errors.QueryError`.

Tokens remember their character offsets in the original SQL so that the
parser can attach the exact expression text (including original spacing) to
select items and order items.
"""

from __future__ import annotations

from typing import List, Optional, Tuple

from .ast import (
    Agg,
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)
from .errors import QueryError

# SQL keywords.  Keywords are matched case-insensitively and may not be used
# as unquoted identifiers.  Function and aggregate names are deliberately not
# keywords, so that a column called ``count`` can still be selected.
_KEYWORDS = frozenset(
    {
        "SELECT",
        "DISTINCT",
        "FROM",
        "WHERE",
        "GROUP",
        "BY",
        "HAVING",
        "ORDER",
        "LIMIT",
        "OFFSET",
        "AS",
        "ASC",
        "DESC",
        "AND",
        "OR",
        "NOT",
        "NULL",
        "TRUE",
        "FALSE",
        "IS",
        "IN",
        "BETWEEN",
        "LIKE",
    }
)

_AGGREGATES = frozenset({"count", "sum", "avg", "min", "max"})

_COMPARISON_OPS = frozenset({"=", "!=", "<", "<=", ">", ">="})


class _Token:
    """One lexical token.

    ``kind`` is one of ``kw`` (``value`` upper-cased), ``name`` (identifier,
    quotes removed), ``string``, ``int``, ``float``, ``op`` or ``eof``.
    ``start`` is inclusive and ``end`` exclusive, both as offsets into the SQL.
    ``quoted`` records whether a name came from a double-quoted identifier.
    """

    __slots__ = ("kind", "value", "start", "end", "quoted")

    def __init__(self, kind, value, start, end, quoted=False):
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end
        self.quoted = quoted


def _is_name_start(ch: str) -> bool:
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def _tokenize(sql: str) -> List[_Token]:
    tokens: List[_Token] = []
    i = 0
    n = len(sql)

    while i < n:
        ch = sql[i]

        if ch.isspace():
            i += 1
            continue

        start = i

        if _is_name_start(ch):
            i += 1
            while i < n and (_is_name_start(sql[i]) or _is_digit(sql[i])):
                i += 1
            word = sql[start:i]
            keyword = word.upper()
            if keyword in _KEYWORDS:
                tokens.append(_Token("kw", keyword, start, i))
            else:
                tokens.append(_Token("name", word, start, i))
            continue

        if _is_digit(ch) or (ch == "." and i + 1 < n and _is_digit(sql[i + 1])):
            if ch == ".":
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            else:
                while i < n and _is_digit(sql[i]):
                    i += 1
                if i < n and sql[i] == ".":
                    i += 1
                    while i < n and _is_digit(sql[i]):
                        i += 1
            text = sql[start:i]
            if "." in text:
                tokens.append(_Token("float", float(text), start, i))
            else:
                tokens.append(_Token("int", int(text), start, i))
            continue

        if ch == "'":
            i += 1
            parts = []
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        parts.append("'")
                        i += 2
                        continue
                    i += 1
                    break
                parts.append(sql[i])
                i += 1
            else:
                raise QueryError("unterminated string literal")
            tokens.append(_Token("string", "".join(parts), start, i))
            continue

        if ch == '"':
            i += 1
            parts = []
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        parts.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                parts.append(sql[i])
                i += 1
            else:
                raise QueryError("unterminated quoted identifier")
            tokens.append(_Token("name", "".join(parts), start, i, quoted=True))
            continue

        two = sql[i : i + 2]
        if two == "||":
            tokens.append(_Token("op", "||", start, i + 2))
            i += 2
            continue
        if two in ("<=", ">=", "<>", "!="):
            # ``<>`` and ``!=`` mean the same thing.
            value = "!=" if two == "<>" else two
            tokens.append(_Token("op", value, start, i + 2))
            i += 2
            continue

        if ch in "()*+-/=<>,;":
            tokens.append(_Token("op", ch, start, i + 1))
            i += 1
            continue

        raise QueryError("unexpected character %r" % ch)

    tokens.append(_Token("eof", None, n, n))
    return tokens


class _Parser:
    def __init__(self, sql: str, tokens: List[_Token]):
        self.sql = sql
        self.tokens = tokens
        self.pos = 0

    # -- token helpers ---------------------------------------------------

    def _peek(self, offset: int = 0) -> _Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            index = len(self.tokens) - 1
        return self.tokens[index]

    def _advance(self) -> _Token:
        token = self.tokens[self.pos]
        if token.kind != "eof":
            self.pos += 1
        return token

    def _previous(self) -> _Token:
        return self.tokens[self.pos - 1]

    def _source(self, start: int, end: int) -> str:
        return self.sql[start:end]

    def _at_kw(self, word: str) -> bool:
        token = self._peek()
        return token.kind == "kw" and token.value == word

    def _match_kw(self, word: str) -> bool:
        if self._at_kw(word):
            self._advance()
            return True
        return False

    def _expect_kw(self, word: str) -> _Token:
        if not self._at_kw(word):
            raise QueryError("expected %s" % word)
        return self._advance()

    def _at_op(self, op: str) -> bool:
        token = self._peek()
        return token.kind == "op" and token.value == op

    def _match_op(self, op: str) -> bool:
        if self._at_op(op):
            self._advance()
            return True
        return False

    def _expect_op(self, op: str) -> _Token:
        if not self._at_op(op):
            raise QueryError("expected '%s'" % op)
        return self._advance()

    def _expect_identifier(self, description: str) -> str:
        token = self._peek()
        if token.kind == "name":
            self._advance()
            return token.value
        raise QueryError("expected %s" % description)

    def _describe(self, token: _Token) -> str:
        if token.kind == "eof":
            return "end of query"
        return "'%s'" % self._source(token.start, token.end)

    # -- statement -------------------------------------------------------

    def parse_query(self) -> Query:
        if self._peek().kind == "eof":
            raise QueryError("empty query")
        if not self._match_kw("SELECT"):
            raise QueryError("expected SELECT")

        distinct = self._match_kw("DISTINCT")

        if self._match_op("*"):
            columns: Optional[List[SelectItem]] = None
        else:
            columns = [self._parse_select_item()]
            while self._match_op(","):
                columns.append(self._parse_select_item())

        self._expect_kw("FROM")
        table = self._expect_identifier("table name after FROM")

        where = self._parse_expr() if self._match_kw("WHERE") else None

        group_by: List[Expr] = []
        if self._match_kw("GROUP"):
            self._expect_kw("BY")
            group_by.append(self._parse_expr())
            while self._match_op(","):
                group_by.append(self._parse_expr())

        having = self._parse_expr() if self._match_kw("HAVING") else None

        order_by: List[OrderItem] = []
        if self._match_kw("ORDER"):
            self._expect_kw("BY")
            order_by.append(self._parse_order_item())
            while self._match_op(","):
                order_by.append(self._parse_order_item())

        limit: Optional[int] = None
        offset: Optional[int] = None
        if self._match_kw("LIMIT"):
            limit = self._parse_nonnegative_integer("LIMIT")
            if self._match_kw("OFFSET"):
                offset = self._parse_nonnegative_integer("OFFSET")

        if self._match_op(";"):
            if self._peek().kind != "eof":
                raise QueryError("unexpected text after ';'")

        if self._peek().kind != "eof":
            raise QueryError("unexpected %s" % self._describe(self._peek()))

        return Query(
            distinct=distinct,
            columns=columns,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _parse_select_item(self) -> SelectItem:
        start = self._peek().start
        expr = self._parse_expr()
        text = self._source(start, self._previous().end)
        alias = self._parse_alias()
        return SelectItem(expr, alias, text)

    def _parse_alias(self) -> Optional[str]:
        if self._match_kw("AS"):
            return self._expect_identifier("name after AS")
        token = self._peek()
        if token.kind == "name":
            self._advance()
            return token.value
        return None

    def _parse_order_item(self) -> OrderItem:
        start = self._peek().start
        expr = self._parse_expr()
        text = self._source(start, self._previous().end)
        descending = False
        if self._match_kw("ASC"):
            descending = False
        elif self._match_kw("DESC"):
            descending = True
        return OrderItem(expr, descending, text)

    def _parse_nonnegative_integer(self, clause: str) -> int:
        token = self._peek()
        if token.kind == "int":
            self._advance()
            return token.value
        raise QueryError("%s requires a non-negative integer" % clause)

    # -- expressions -----------------------------------------------------

    def _parse_expr(self) -> Expr:
        return self._parse_or()

    def _parse_or(self) -> Expr:
        left = self._parse_and()
        while self._match_kw("OR"):
            left = Binary("OR", left, self._parse_and())
        return left

    def _parse_and(self) -> Expr:
        left = self._parse_not()
        while self._match_kw("AND"):
            left = Binary("AND", left, self._parse_not())
        return left

    def _parse_not(self) -> Expr:
        if self._match_kw("NOT"):
            return Unary("NOT", self._parse_not())
        return self._parse_comparison()

    def _parse_comparison(self) -> Expr:
        left = self._parse_additive()
        while True:
            token = self._peek()
            if token.kind == "op" and token.value in _COMPARISON_OPS:
                self._advance()
                left = Binary(token.value, left, self._parse_additive())
                continue

            if token.kind != "kw":
                break

            if token.value == "IS":
                self._advance()
                negated = self._match_kw("NOT")
                if not self._match_kw("NULL"):
                    raise QueryError("expected NULL after IS")
                left = IsNull(left, negated)
                continue

            if token.value in ("IN", "BETWEEN", "LIKE"):
                self._advance()
                left = self._parse_comparison_tail(left, token.value, False)
                continue

            if token.value == "NOT":
                following = self._peek(1)
                if following.kind == "kw" and following.value in (
                    "IN",
                    "BETWEEN",
                    "LIKE",
                ):
                    self._advance()  # NOT
                    op = self._advance().value
                    left = self._parse_comparison_tail(left, op, True)
                    continue
                raise QueryError("expected IN, BETWEEN, or LIKE after NOT")

            break

        return left

    def _parse_comparison_tail(self, left: Expr, op: str, negated: bool) -> Expr:
        if op == "IN":
            self._expect_op("(")
            if self._at_op(")"):
                raise QueryError("IN requires at least one value")
            items = [self._parse_expr()]
            while self._match_op(","):
                items.append(self._parse_expr())
            self._expect_op(")")
            return InList(left, tuple(items), negated)

        if op == "BETWEEN":
            # The bounds use the arithmetic precedence levels so that the
            # ``AND`` belonging to BETWEEN is the only one consumed here;
            # a following boolean AND belongs to an enclosing expression.
            low = self._parse_additive()
            if not self._match_kw("AND"):
                raise QueryError("expected AND in BETWEEN")
            high = self._parse_additive()
            return Between(left, low, high, negated)

        # LIKE
        pattern = self._parse_additive()
        return Like(left, pattern, negated)

    def _parse_additive(self) -> Expr:
        left = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind == "op" and token.value in ("+", "-", "||"):
                self._advance()
                left = Binary(token.value, left, self._parse_multiplicative())
            else:
                break
        return left

    def _parse_multiplicative(self) -> Expr:
        left = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind == "op" and token.value in ("*", "/"):
                self._advance()
                left = Binary(token.value, left, self._parse_unary())
            else:
                break
        return left

    def _parse_unary(self) -> Expr:
        if self._match_op("-"):
            return Unary("-", self._parse_unary())
        return self._parse_primary()

    def _parse_primary(self) -> Expr:
        token = self._peek()

        if token.kind in ("int", "float", "string"):
            self._advance()
            return Literal(token.value)

        if token.kind == "kw":
            if token.value == "NULL":
                self._advance()
                return Literal(None)
            if token.value == "TRUE":
                self._advance()
                return Literal(True)
            if token.value == "FALSE":
                self._advance()
                return Literal(False)
            raise QueryError("expected expression")

        if token.kind == "name":
            self._advance()
            if not token.quoted and self._at_op("("):
                return self._parse_call(token)
            # A quoted identifier is never a function name; if it happens to
            # be followed by ``(`` the caller will report the syntax error.
            return Column(token.value)

        if token.kind == "op" and token.value == "(":
            self._advance()
            expr = self._parse_expr()
            self._expect_op(")")
            return expr

        if token.kind == "eof":
            raise QueryError("expected expression")
        raise QueryError("unexpected %s" % self._describe(token))

    def _parse_call(self, name_token: _Token) -> Expr:
        name = name_token.value.lower()
        self._expect_op("(")

        if self._match_op("*"):
            if name != "count":
                raise QueryError("only COUNT may use '*' as its argument")
            self._expect_op(")")
            return Agg("count", (), star=True)

        args: List[Expr] = []
        if not self._at_op(")"):
            args.append(self._parse_expr())
            while self._match_op(","):
                args.append(self._parse_expr())
        self._expect_op(")")

        if name in _AGGREGATES:
            return Agg(name, tuple(args), star=False)
        return Func(name, tuple(args))


def parse(sql: str) -> Query:
    """Parse one ``SELECT`` statement.

    Raises :class:`minisql.errors.QueryError` for any lexical or grammatical
    problem.
    """
    tokens = _tokenize(sql)
    return _Parser(sql, tokens).parse_query()
